function PreviewDataPicker({ clients, programs, value, onChange }) {
  const [programId,setProgramId]=React.useState("all"),[query,setQuery]=React.useState(""),[open,setOpen]=React.useState(false);
  const normalizedQuery=clean(query).toLocaleLowerCase("ar");
  const filtered=React.useMemo(()=>clients.filter((client)=>{
    if(programId!=="all"&&String(client.programId||client.program_id)!==programId)return false;
    const passport=client.passport||{},searchable=`${client.name||""} ${passport.number||passport.passportNumber||passport.passport_number||""}`.toLocaleLowerCase("ar");
    return !normalizedQuery||searchable.includes(normalizedQuery);
  }),[clients,programId,normalizedQuery]);
  const selected=clients.find((client)=>String(client.id)===String(value));
  return <SmartBadgeUi><div className="smart-badge-preview-picker">
    <label><span>البرنامج</span><select value={programId} onChange={(event)=>{setProgramId(event.target.value);setOpen(true);}}><option value="all">كل البرامج</option>{programs.map((program)=><option key={program.id} value={program.id}>{program.name||program.nameFr||"برنامج"}</option>)}</select></label>
    <label><span>ابحث عن معتمر</span><input type="search" value={query} placeholder="الاسم أو رقم الجواز" onFocus={()=>setOpen(true)} onChange={(event)=>{setQuery(event.target.value);setOpen(true);}}/></label>
    <button type="button" className="smart-badge-picker-trigger" aria-expanded={open} onClick={()=>setOpen((current)=>!current)}><span>{selected?.name||"بيانات معاينة"}</span><b>⌄</b></button>
    {open&&<div className="smart-badge-picker-list" role="listbox"><button type="button" className={!value?"is-selected":""} onClick={()=>{onChange("");setOpen(false);}}>بيانات معاينة</button>{filtered.map((client)=><button type="button" role="option" aria-selected={String(client.id)===String(value)} className={String(client.id)===String(value)?"is-selected":""} key={client.id} onClick={()=>{onChange(client.id);setOpen(false);}}><strong>{client.name||"معتمر"}</strong><small>{programs.find((program)=>String(program.id)===String(client.programId||client.program_id))?.name||""}</small></button>)}{!filtered.length&&<p>لا توجد نتائج مطابقة</p>}</div>}
  </div></SmartBadgeUi>;
}

export function buildSmartBadgeData(client, programs, travelGroups) {
  if (!client) return previewData;
  const program = programs.find((item) => String(item.id) === String(client.programId || client.program_id)) || (programs.length===1?programs[0]:{});
  const group = travelGroups.find((item) => String(item.id) === String(client.travelGroupId || client.travel_group_id)) || {};
  const passport = client.passport || {};
  const rooming = client.docs?.rooming || {};
  const packages=Array.isArray(program.packages)?program.packages:[],packageId=client.packageId||client.package_id,packageLevel=client.packageLevel||client.hotelLevel||client.hotel_level,selectedPackage=packages.find((item)=>String(item.id)===String(packageId))||packages.find((item)=>String(item.level||item.name)===String(packageLevel))||{};
  const guidePhone=badgePhonesFromProgram(program)[0]||"";
  return { name:clean(client.name || [client.firstName,client.lastName].filter(Boolean).join(" ")),passport:clean(passport.number || passport.passportNumber || passport.passport_number || passport.no || client.passportNumber),program:clean(program.name || program.nameFr),group:clean(group.name || group.code || client.travelGroupName),room:clean(rooming.roomNumber || rooming.room_number || client.roomNumber),makkahHotel:clean(client.hotelMecca||client.hotel_mecca||selectedPackage.hotelMecca||selectedPackage.hotel_mecca||program.hotelMecca||program.hotel_mecca),madinahHotel:clean(client.hotelMadina||client.hotel_madina||selectedPackage.hotelMadina||selectedPackage.hotel_madina||program.hotelMadina||program.hotel_madina),city:clean(client.city),phone:clean(client.phone),guidePhone:clean(guidePhone),travelDate:clean(group.departureDate || group.departure_date || program.departure) };
}

function PrecisionControl({ label, hint="", value, min, max, unit="mm", step=BADGE_GRID_MM, onChange }) {
  const safeValue = clamp(value, min, max);
  const change = (next) => onChange(Math.round(clamp(next, min, max) / step) * step);
  return <div className="smart-badge-precision"><span>{label}{hint&&<small> — {hint}</small>}</span><input aria-label={`${label} slider`} type="range" min={min} max={max} step={step} value={safeValue} onChange={(event) => change(event.target.value)} /><div><button type="button" onClick={() => change(safeValue-step)}>−</button><label><input aria-label={label} type="number" min={min} max={max} step={step} value={safeValue} onChange={(event) => change(event.target.value)} /><small>{unit}</small></label><button type="button" onClick={() => change(safeValue+step)}>+</button></div></div>;
}

function ColorControl({ label, value, onChange }) {
  return <div className="smart-badge-field smart-badge-color-row"><span>{label}</span><input aria-label={label} title={label} className="smart-badge-color" type="color" value={value} onChange={(event)=>onChange(event.target.value)}/></div>;
}

function SegmentedControl({ label, value, options, onChange }) {
  return <SmartBadgeUi><div className="smart-badge-option-group"><span>{label}</span><div className="smart-badge-mini-segments" role="group" aria-label={label}>{options.map(([option,text])=><button aria-pressed={value===option} className={value===option?"is-active":""} type="button" key={option} onClick={()=>onChange(option)}>{text}</button>)}</div></div></SmartBadgeUi>;
}

